INSERT INTO "email_logs" ("log_id", "recipient_email", "subject", "message", "status", "created_at") VALUES ('1', 'alucardking35@gmail.com', 'Reset Your Password', '
        <div style=''font-family:Arial,sans-serif;padding:30px;background:#f8fafc;''>

            <div style=''max-width:600px;margin:auto;background:#ffffff;border-radius:12px;padding:40px;''>

